<?php
declare(strict_types=1);

namespace Bank;

/**
 * Key material lives in storage/keys.php (mode 0600), generated by the setup wizard.
 * In production put these in a KMS/HSM and load them from there instead.
 *
 * It is a plain `.php` file that `return`s the keys as an array - not `.json` - on purpose: this
 * project keeps `storage/` in the same folder tree the web server serves (see README), and every
 * file in it starts with a guard that checks for the BANK_INTERNAL constant bootstrap.php defines.
 * Requesting the file's URL directly starts a fresh PHP process with no such constant, so the guard
 * exits with 403 before the key array is ever reached; `require`ing it from inside the app defines
 * the constant first, so the guard is a no-op and the array loads normally.
 *
 * Built entirely on the `openssl` extension (bundled with every standard PHP build):
 *   - AES-256-GCM for data encrypted at rest (TOTP secrets, ID numbers)
 *   - HMAC-SHA256 (core PHP, no extension needed) for low-entropy secrets (OTPs, recovery codes)
 */
final class Crypto
{
    private const CIPHER = 'aes-256-gcm';
    private const IV_LEN = 12;
    private const TAG_LEN = 16;
    private const GUARD = "<?php\nif (!defined('BANK_INTERNAL')) { http_response_code(403); exit; }\nreturn ";

    private static ?array $keys = null;

    public static function keyfilePath(): string
    {
        return Config::get('storage') . '/keys.php';
    }

    public static function generateKeyfile(): void
    {
        $data = [
            'secretbox' => b64(random_bytes(32)),   // AES-256 key
            'hmac'      => b64(random_bytes(32)),
        ];
        $path = self::keyfilePath();
        file_put_contents($path, self::GUARD . var_export($data, true) . ";\n");
        chmod($path, 0600);
        self::$keys = null;
    }

    public static function reset(): void
    {
        self::$keys = null;
    }

    private static function keys(): array
    {
        if (self::$keys === null) {
            $path = self::keyfilePath();
            if (!is_file($path)) {
                throw new \RuntimeException('Key file missing - visit setup.php to initialise the bank.');
            }
            self::$keys = require $path;
        }
        return self::$keys;
    }

    /** Authenticated encryption for data at rest (TOTP secrets, ID numbers). */
    public static function encrypt(string $plain): string
    {
        $iv = random_bytes(self::IV_LEN);
        $tag = '';
        $cipher = openssl_encrypt($plain, self::CIPHER, unb64(self::keys()['secretbox']), OPENSSL_RAW_DATA, $iv, $tag, '', self::TAG_LEN);
        if ($cipher === false) {
            throw new \RuntimeException('Encryption failed: ' . openssl_error_string());
        }
        return b64($iv . $tag . $cipher);
    }

    public static function decrypt(string $blob): string
    {
        $raw = unb64($blob);
        if (strlen($raw) < self::IV_LEN + self::TAG_LEN) {
            throw new \RuntimeException('Decryption failed');
        }
        $iv = substr($raw, 0, self::IV_LEN);
        $tag = substr($raw, self::IV_LEN, self::TAG_LEN);
        $cipher = substr($raw, self::IV_LEN + self::TAG_LEN);
        $plain = openssl_decrypt($cipher, self::CIPHER, unb64(self::keys()['secretbox']), OPENSSL_RAW_DATA, $iv, $tag);
        if ($plain === false) {
            throw new \RuntimeException('Decryption failed');
        }
        return $plain;
    }

    /** Keyed hash for low-entropy secrets such as 6-digit OTPs and recovery codes. */
    public static function mac(string $data): string
    {
        return hash_hmac('sha256', $data, unb64(self::keys()['hmac']));
    }
}
